var i=`0422-fl-skesteg`;var t=`world-0422`;var a=`DK`;var s=`northern-europe`;var o=4;var r=121;var l={en:`Flæskesteg`,ua:`Флескестег`};var d={en:`A traditional dish from Denmark, centered on pork loin, bay leaf, potato, red cabbage. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Данія. Основні складники: свиняча корейка, лавровий лист, картопля, червоноголова капуста. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:5,i:[[`pork-loin`,1100,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`],[`bay-leaf`,2,`leaf`]]},{en:`Roast in a preheated 190°C oven for about 90 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 90 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:90,i:[[`sunflower-oil`,35,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 23 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 23 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:23,i:[[`potato`,800,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`red-cabbage`,350,`g`]]}];var u={slug:i,id:t,country:`DK`,region:s,servings:4,minutes:121,title:l,text:d,steps:g};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,i as slug,g as steps,d as text,l as title};